  padding: 0;
}

/* ─── Design tokens ─────────────────────────────────────────────── */
:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141c;
  --border-default: #2e3248;
  --border-focus:   #7b84ff;
  --border-error:   #f87171;
  --text-primary:   #e8eaf6;
  --text-secondary: #9198b5;
  --text-label:     #c5c9e0;
  --text-placeholder: #555a78;
  --accent:         #7b84ff;
  --accent-hover:   #6068f0;
  --accent-active:  #4e56e0;
  --error-color:    #f87171;
  --success-color:  #4ade80;
  --focus-ring:     0 0 0 3px rgba(123, 132, 255, 0.45);
  --radius-input:   8px;
  --radius-card:    16px;
  --transition:     150ms ease;
}

/* ─── Body & layout ─────────────────────────────────────────────── */
body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-primary);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.6;
}

/* ─── Skip link ─────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  z-index: 999;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-input) var(--radius-input);
  font-weight: 600;
  text-decoration: none;
}
.skip-link:focus {
  top: 0;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* ─── Screen-reader only ─────────────────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ─── Form card ─────────────────────────────────────────────────── */
.form-card {
  width: 100%;
  max-width: 480px;
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-card);
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.55);
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.form-intro {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ─── Live regions ─────────────────────────────────────────────── */
#form-error-summary,
#form-success {
  /* always in DOM; show only when non-empty */
  border-radius: var(--radius-input);
  font-size: 0.875rem;
  font-weight: 600;
  padding: 0;
  overflow: hidden;
  max-height: 0;
  transition: max-height var(--transition), padding var(--transition);
}

#form-error-summary:not(:empty) {
  background: rgba(248, 113, 113, 0.1);
  border: 1px solid var(--error-color);
  color: var(--error-color);
  padding: 0.75rem 1rem;
  max-height: 10rem;
  margin-bottom: 1.25rem;
}

#form-success:not(:empty) {
  background: rgba(74, 222, 128, 0.1);
  border: 1px solid var(--success-color);
  color: var(--success-color);
  padding: 0.75rem 1rem;
  max-height: 10rem;
  margin-bottom: 1.25rem;
}

/* ─── Form field wrapper ─────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.4rem;
}

/* ─── Labels ─────────────────────────────────────────────────────── */
label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-label);
  display: flex;
  align-items: center;
  gap: 0.2rem;
}

.required-marker {
  color: #f87171;
  font-size: 1rem;
  line-height: 1;
}

.optional-label {
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--text-secondary);
  margin-left: 0.15rem;
}

/* ─── Inputs ─────────────────────────────────────────────────────── */
input {
  width: 100%;
  padding: 0.65rem 0.875rem;
  background: var(--bg-input);
  color: var(--text-primary);
  border: 1.5px solid var(--border-default);
  border-radius: var(--radius-input);
  font-size: 0.95rem;
  font-family: inherit;
  line-height: 1.5;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}

input::placeholder {
  color: var(--text-placeholder);
}

input:hover {
  border-color: #3e4460;
}

input:focus {
  border-color: var(--border-focus);
  box-shadow: var(--focus-ring);
}

/* Invalid state */
input[aria-invalid="true"] {
  border-color: var(--border-error);
}
input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.35);
}

/* Valid state (after user interaction) */
input.is-valid {
  border-color: #4ade80;
}

