        return '';
      },
    },
    email: {
      el: document.getElementById('email'),
      errorEl: document.getElementById('email-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Email address is required.';
        // RFC-5321-inspired simple pattern
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return 'Error: Enter a valid email address, e.g. name@example.com.';
        }
        return '';
      },
    },
    phone: {
      el: document.getElementById('phone'),
      errorEl: document.getElementById('phone-error'),
      validate(value) {
        if (!value.trim()) return ''; // optional
        // Accept common North-American and international formats
        if (!/^[+]?[\d\s\-().]{7,20}$/.test(value.trim())) {
          return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000 or 555-000-0000.';
        }
        return '';
      },
    },
  };

  /* ── Per-field helpers ─────────────────────────────────────────── */

  function setFieldState(field, errorMsg) {
    const { el, errorEl } = field;
    if (errorMsg) {
      errorEl.textContent = errorMsg;
      el.setAttribute('aria-invalid', 'true');
      el.classList.remove('is-valid');
    } else {
      errorEl.textContent = '';
      el.removeAttribute('aria-invalid');
      // Only mark valid if the user has entered something
      if (el.value.trim()) el.classList.add('is-valid');
      else el.classList.remove('is-valid');
    }
  }

  function validateField(fieldKey) {
    const field = fields[fieldKey];
    const msg = field.validate(field.el.value);
    setFieldState(field, msg);
    return msg;
  }

  /* ── Live inline validation on blur ───────────────────────────── */

  Object.keys(fields).forEach((key) => {
    const { el } = fields[key];

    el.addEventListener('blur', () => {
      validateField(key);
    });

    // Clear error as soon as the user starts correcting
    el.addEventListener('input', () => {
      if (el.getAttribute('aria-invalid') === 'true') {
        validateField(key);
      }
    });
  });

  /* ── Submit ─────────────────────────────────────────────────────── */

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Clear any previous success message
    successRegion.textContent = '';

