}

/* ─── Design tokens ─────────────────────────────────────────────── */
:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141c;
  --border-default: #2e3248;
  --border-focus:   #7b84ff;
